function MULT_ORDER(a, m):
    if m <= 1 or gcd(a, m) != 1: return NONE
    x <- a mod m;  k <- 1
    while x != 1:
        x <- (x * a) mod m
        k <- k + 1
    return k                       # equals seqRank(n -> a^n - 1, m)

